    records = _audit._read_all_records(audit_path)
    prev = records[-1][_audit.HASH] if records else _audit._ZERO_HASH
    without_hash = {
        _audit.DETAIL: event[_audit.DETAIL],
        _audit.KIND: event[_audit.KIND],
