        audit_digest = existing[AUDIT]
        stage = existing[STAGE]
        if stage == PREPARED and audit_digest != planned_audit_digest:
            # Before the event is appended its record hash must still be
            # derivable from the log tail; a different bound digest means
            # this request conflicts with the recorded one.
            raise ValueError(
                f"checkpoint id {checkpoint_id!r} is already bound to a "
                "different audit digest"
            )

