            else:
                raise ValueError(
                    f"checkpoint id {checkpoint_id!r} is past stage 'state' "
                    "but its audit record is missing"
                )
        else:
            if not _event_matches(audit_record, event):
                raise ValueError(
                    f"checkpoint id {checkpoint_id!r} audit record does not "
                    "match its committed event"
                )
            append_pending = False
    else:
        append_pending = not state_done or stage == PREPARED

    if stage in (STAGE_AUDIT, COMMITTED):
        if bound_receipt is None:
            raise ValueError(
                f"checkpoint id {checkpoint_id!r} is past stage 'audit' but "
                "its receipt is missing"
            )
        if (
            bound_receipt[STATE] != state_digest
            or bound_receipt[AUDIT] != audit_digest
        ):
            raise ValueError(
                f"checkpoint id {checkpoint_id!r} receipt is bound to "
                "different state or audit digests"
            )
        receipt_pending = False
    elif stage == STAGE_STATE and audit_record is not None:
        # Crash between the receipt-less ... actually receipt may already
        # be bound if the commit crashed after putting it; equal is fine.
        if bound_receipt is not None and (
            bound_receipt[STATE] != state_digest
            or bound_receipt[AUDIT] != audit_digest
        ):
            raise ValueError(
                f"receipt id {checkpoint_id!r} is already bound to "
                "different state or audit digests"
            )
        receipt_pending = bound_receipt is None
    else:
        receipt_pending = False

    # All checks passed; perform each remaining effect exactly once,
    # advancing the checkpoint after every durable step.
    if existing is None:
        records = _advance(
            checkpoint_path, records, checkpoint_id,
            state_digest, audit_digest, PREPARED,
        )

    if stage == PREPARED:
        if not state_done:
            _storage.save_state(state_path, state)
        records = _advance(
            checkpoint_path, records, checkpoint_id,
            state_digest, audit_digest, STAGE_STATE,
        )
        stage = STAGE_STATE

    if stage == STAGE_STATE and append_pending:
        _audit.append(audit_path, event)
    if stage == STAGE_STATE:
        records = _advance(
            checkpoint_path, records, checkpoint_id,
            state_digest, audit_digest, STAGE_AUDIT,
        )
        stage = STAGE_AUDIT

    if stage == STAGE_AUDIT and receipt_pending:
        _receipt.put(
            receipt_path,
            {AUDIT: audit_digest, ID: checkpoint_id, STATE: state_digest},
        )
    if stage == STAGE_AUDIT:
        records = _advance(
            checkpoint_path, records, checkpoint_id,
            state_digest, audit_digest, COMMITTED,
        )
        stage = COMMITTED

    return {
        AUDIT: audit_digest,
        ID: checkpoint_id,
        STAGE: COMMITTED,
        STATE: state_digest,
    }
